      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방 용량이 평소 용량의 두 배였다는 차이에 연결해, 용량의 적절성이 확인되기 전에는 투약하지 않는다는 보류 기준을 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 처방이 의심스러우면 투약을 보류한다는 기준은 제시하지만, 해당 처방의 용량 차이나 확인 전 투약 여부에 적용한 설명은 일반론에 그친다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 보류한 판단 기준을 제시하지 않거나, 처방 용량에 대한 판단 대신 다른 투약 업무만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
